#!/usr/bin/env python3
"""Durable key-value record service on port 8080 (stdlib only).

GET /health        -> 200, body "ready"
PUT /records/<id>  -> 204, stores raw request body
GET /records/<id>  -> 200, returns exact stored body (404 if unknown)
"""

import os
import re
import tempfile
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

HOST = "0.0.0.0"
PORT = 8080
RECORDS_DIR = "/var/lib/builder-app/records"

SAFE_ID = re.compile(r"^[A-Za-z0-9._~-]+$")


def record_path(record_id: str) -> str:
    if not record_id or not SAFE_ID.match(record_id) or record_id in (".", ".."):
        raise ValueError("invalid record id")
    return os.path.join(RECORDS_DIR, record_id)


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "builder-app/1.0"

    def _send(self, status: int, body: bytes = b"", content_type: str = "application/octet-stream"):
        self.send_response(status)
        if body or status not in (204,):
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
        else:
            self.send_header("Content-Length", "0")
        self.end_headers()
        if body and self.command != "HEAD":
            self.wfile.write(body)

    def do_GET(self):
        path = self.path.split("?", 1)[0]
        if path == "/health":
            self._send(200, b"ready", "text/plain")
            return
        if path.startswith("/records/"):
            record_id = path[len("/records/"):]
            try:
                path_on_disk = record_path(record_id)
            except ValueError:
                self._send(400, b"invalid record id\n", "text/plain")
                return
            try:
                with open(path_on_disk, "rb") as f:
                    data = f.read()
            except FileNotFoundError:
                self._send(404, b"not found\n", "text/plain")
                return
            self._send(200, data)
            return
        self._send(404, b"not found\n", "text/plain")

    def do_HEAD(self):
        self.do_GET()

    def do_PUT(self):
        path = self.path.split("?", 1)[0]
        if not path.startswith("/records/"):
            self._send(404, b"not found\n", "text/plain")
            return
        record_id = path[len("/records/"):]
        try:
            path_on_disk = record_path(record_id)
        except ValueError:
            self._send(400, b"invalid record id\n", "text/plain")
            return

        try:
            length = int(self.headers.get("Content-Length", "0"))
        except ValueError:
            self._send(400, b"bad content-length\n", "text/plain")
            return
        if length < 0:
            self._send(400, b"bad content-length\n", "text/plain")
            return
        data = self.rfile.read(length) if length else b""

        os.makedirs(RECORDS_DIR, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=RECORDS_DIR, prefix=".tmp-")
        try:
            with os.fdopen(fd, "wb") as f:
                f.write(data)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, path_on_disk)
            # Persist the directory entry so the record survives power loss.
            dir_fd = os.open(RECORDS_DIR, os.O_RDONLY)
            try:
                os.fsync(dir_fd)
            finally:
                os.close(dir_fd)
        except BaseException:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise
        self._send(204)

    def log_message(self, fmt, *args):
        pass  # keep the journal quiet


class Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True


if __name__ == "__main__":
    os.makedirs(RECORDS_DIR, exist_ok=True)
    Server((HOST, PORT), Handler).serve_forever()

